<?php
namespace App\Models;use Illuminate\Database\Eloquent\Factories\HasFactory;use Illuminate\Database\Eloquent\Model;
class MeasurementPoint extends Model{use HasFactory;protected $fillable=['survey_id','survey_run_id','floor_plan_id','survey_area_id','captured_by','x_normalized','y_normalized','source_type','collection_method','validation_status','notes','captured_at'];protected function casts():array{return ['x_normalized'=>'decimal:6','y_normalized'=>'decimal:6','captured_at'=>'datetime'];}public function survey(){return $this->belongsTo(Survey::class);}public function run(){return $this->belongsTo(SurveyRun::class,'survey_run_id');}public function floorPlan(){return $this->belongsTo(FloorPlan::class);}public function capturedBy(){return $this->belongsTo(User::class,'captured_by');}public function measurements(){return $this->hasMany(Measurement::class);}}
